 'exportSetOut': {title:'Взять конец отсюда',purpose:'Подставляет в поле конца текущее положение курсора.',usage:'Поставь курсор на нужный конец и нажми эту кнопку.'},
 'exportFullRange': {title:'Сохранить весь ролик',purpose:'Выбирает весь монтаж от начала до конца.',usage:'Нажми, если не хочешь сохранять только отдельный кусок.',tip:'Проверь, нет ли пустого места после последнего клипа.'},
 'exportClose': {title:'Закрыть настройки сохранения',purpose:'Закрывает окно экспорта.',usage:'Если сохранение ещё идёт, сначала дождись завершения или отмени его.'},
 'exportCancel': {title:'Остановить сохранение',purpose:'Останавливает текущую запись или запрашивает безопасное завершение FFmpeg.',usage:'Нажми, если передумал. Дождись сообщения, что остановка завершена.',tip:'Частично сохранённый файл может быть неполным.'},
 'exportStart': {title:'Сохранить готовое видео',purpose:'Запускает сборку видео с выбранными настройками.',usage:'Проверь формат и размер, затем нажми кнопку и дождись окончания.',tip:'Не закрывай вкладку во время экспорта. После сохранения открой видео и проверь звук.'},
 'pfStart': {title:'Где клип стоит в ролике',purpose:'Задаёт момент, когда этот клип начинается на шкале монтажа.',usage:'Измени время, если нужно передвинуть клип. Это не меняет начало самого видео внутри клипа.'},
