 'pfScale': {title:'Увеличить или уменьшить картинку',purpose:'Меняет размер изображения в кадре.',usage:'Увеличивай понемногу и смотри результат в окне просмотра.',tip:'При большом увеличении края изображения могут обрезаться.'},
 'pfPosX': {title:'Сдвинуть картинку влево или вправо',purpose:'Меняет положение изображения по горизонтали.',usage:'Измени число и посмотри, куда сдвинулся объект.'},
