 'pfFlipH': {title:'Отразить слева направо',purpose:'Переворачивает изображение как в зеркале.',usage:'Включи флажок, чтобы поменять левую и правую стороны.'},
 'pfFlipV': {title:'Перевернуть вверх ногами',purpose:'Переворачивает картинку сверху вниз.',usage:'Включай только если изображение действительно нужно перевернуть.'},
