 'pfResetTransform': {title:'Вернуть обычный размер и положение',purpose:'Отменяет увеличение, сдвиг, поворот и отражение у выбранного клипа.',usage:'Нажми, если картинка случайно уехала или повернулась.',tip:'Цвет и текст при этом не сбрасываются.'},
 'pfBrightness': {title:'Сделать картинку светлее или темнее',purpose:'Меняет общую яркость изображения.',usage:'Передвигай настройку понемногу и следи, чтобы светлые места не стали белыми пятнами.'},
 'pfContrast': {title:'Сделать светлое и тёмное заметнее',purpose:'Усиливает или уменьшает разницу между светлыми и тёмными частями картинки.',usage:'Меняй немного за раз, чтобы не потерять детали в тенях.'},
 'pfSaturation': {title:'Сделать цвета ярче или бледнее',purpose:'Меняет силу цветов.',usage:'100% — как в исходнике, 0% — чёрно-белое изображение.'},
 'pfLookPreset': {title:'Готовый цветовой стиль',purpose:'Применяет готовый оттенок, например тёплый, холодный или под старую плёнку.',usage:'Выбери стиль и сравни с оригиналом.'},
 'pfResetColor': {title:'Вернуть исходные цвета',purpose:'Сбрасывает изменения яркости, контраста и насыщенности.',usage:'Нажми, если цвет стал выглядеть неестественно.',tip:'Размер и положение картинки не изменятся.'},
 'pfTitleText': {title:'Написать текст на видео',purpose:'Добавляет надпись поверх картинки.',usage:'Введи заголовок или короткую подпись и посмотри результат в окне просмотра.',tip:'Не закрывай текстом лицо или важные детали.'},
 'pfTitleFontSize': {title:'Размер надписи',purpose:'Делает текст крупнее или мельче.',usage:'Подбери размер так, чтобы надпись легко читалась и не закрывала кадр.'},
 'pfTitleColor': {title:'Цвет надписи',purpose:'Выбирает цвет текста на видео.',usage:'Выбери цвет, который хорошо заметен на фоне.'},
 'pfTitlePosition': {title:'Где расположить надпись',purpose:'Выбирает место текста в кадре.',usage:'Попробуй верх, центр или низ. Оставляй отступ от края.'},
 'pfTitleBackground': {title:'Добавить фон под надпись',purpose:'Показывает полупрозрачную подложку за текстом, чтобы его было легче читать.',usage:'Включи, если буквы сливаются с изображением.'},
 'pfVolume': {title:'Сделать звук громче или тише',purpose:'Меняет громкость звука именно этого клипа.',usage:'100% — исходная громкость, 0% — звук выключен.',tip:'Если звучит несколько дорожек, общий звук может стать слишком громким.'},
 'pfFadeIn': {title:'Плавно включить звук',purpose:'Постепенно увеличивает громкость в начале клипа.',usage:'Попробуй 0,5–1 секунду, чтобы звук не начинался резко.'},
 'pfFadeOut': {title:'Плавно выключить звук',purpose:'Постепенно уменьшает громкость к концу клипа.',usage:'Добавь небольшое затухание, чтобы звук не обрывался внезапно.'},
